-- CA_0219_la_community_college_boards_batch2.sql
-- CA_0219: LA County community college boards -- Cerritos Community College District, Compton Community College District, Long Beach Community College District, El Camino Community College District.
--
-- MODEL (new: the DB had NO community-college rows at all -- no government, chamber, district, polygon or office):
--   per college district: one government ("<District>, California, US", LOCAL) + one chamber "Board of Trustees";
--   by-trustee-area boards: one SCHOOL district + one X0002 polygon per area (geo_id '<slug>-ta-N'), one office each;
--   at-large boards: one SCHOOL district + one X0002 polygon for the whole college district, one office per seat.
--   X0002 is the layer both GEOFENCE_DISTRICT_JOIN and MTFCC_DISTRICT_TYPE_GUARD admit for SCHOOL.
-- POLYGONS: LA RR/CC master precinct layer (public.gis.lacounty.gov/.../Political_Boundaries/MapServer/34, 33,236
--   precincts) dissolved by DST_JRC (college district) / DIV_JRC (trustee area). DIV_JRC = the trustee-area number:
--   checked against the colleges' own area descriptions for Compton, Rio Hondo, Long Beach, Pasadena and Citrus
--   (every area's communities match). Slivers < 100 m2 dropped, simplified at 2e-6 deg, make_valid. Local QA: each
--   district's areas union to its whole-district dissolve (ratio 1.00000), max pair overlap < 1.1e-8 deg2, and no two
--   college districts overlap.
-- TRUSTEES: each college's own board page (read 2026-09-23), cross-checked with RR/CC candidate lists + results for
--   Nov 2022 (id 4300), Nov 2024 (4324), Jun 2022 (4269), Mar 2024 (4316). Term start: Nov-election winners
--   YYYY-12-01 'month' 'elected' (house convention); primary-cycle PCC: sourced month or 'year'; appointees: the
--   appointment date 'day' 'appointed'. Party is never stored.
-- CANDIDATES: RR/CC Nov 3 2026 list (lavote.gov/Apps/CandidateList/Index?id=4348); only names whose nomination
--   papers were FILED (arg[8]) -- papers-only names are excluded. Uncontested seats are seeded too (operator
--   decision 2026-09-22). Incumbents (RR/CC flag E/A) are linked to the seated trustee; challengers unlinked.
-- RACES go on '2026 LA County General' (d91a20ce-557e-4615-a31b-5b2b3df2ed14); primary_party NULL.
-- Apply with: npx tsx scripts/_apply-file.ts <abs path>   (geometry-heavy; do not paste through MCP).
--
-- Cerritos Community College District (7 trustee areas; RR/CC DST_JRC 1; https://www.cerritos.edu/board/):
--   TA 1: Mariana Pacheco -- elected 2024-12-01 (month) [reused row c319044d]
--   TA 2: Dawn Green -- elected 2024-12-01 (month) [reused row a8d55cc2]
--   TA 3: James Cody Birkey -- elected 2022-12-01 (month)
--   TA 4: Mariana Rios -- elected 2024-12-01 (month)
--   TA 5: Shin Liu -- elected 2022-12-01 (month)
--   TA 6: Sandra Salazar -- elected 2024-12-01 (month)
--   TA 7: Zurich Lewis -- elected 2022-12-01 (month)
-- Compton Community College District (5 trustee areas; RR/CC DST_JRC 11; https://www.compton.edu/district/board-of-trustees/index.aspx):
--   TA 1: Andres Ramos -- elected 2022-12-01 (month)
--   TA 2: Nicole J. Jones -- appointed 2026-03-09 (day)
--   TA 3: Sonia Lopez -- elected 2024-12-01 (month)
--   TA 4: Juanita Doplemore -- elected 2022-12-01 (month)
--   TA 5: Sharoni Denise Little -- elected 2022-12-01 (month)
-- Long Beach Community College District (5 trustee areas; RR/CC DST_JRC 16; https://www.lbcc.edu/board-trustees):
--   TA 1: Uduak-Joe Ntuk -- elected 2022-12-01 (month)
--   TA 2: Vivian Malauulu -- elected 2024-12-01 (month) [reused row 661de009]
--   TA 3: Sunny Zia -- elected 2022-12-01 (month)
--   TA 4: Ennette Morton -- elected 2024-12-01 (month)
--   TA 5: Virginia L. Baxter -- elected 2022-12-01 (month)
-- El Camino Community College District (5 trustee areas; RR/CC DST_JRC 35; https://www.elcamino.edu/leadership/trustees/index.php):
--   TA 1: Brett C.S. Roberts -- elected 2024-12-01 (month) [reused row 6b20c5ef]
--   TA 2: Nilo Vega Michelin -- elected 2022-12-01 (month)
--   TA 3: Trisha Murakawa -- elected 2024-12-01 (month)
--   TA 4: Katherine Steinbroner Maschler -- elected 2024-12-01 (month)
--   TA 5: MyLoc Dinh -- appointed 2025-12-18 (day)
--
-- BATCH NOTES:
--   CERRITOS CCD: 7 trustee areas; 2026 ballot TA 3, 5, 7 (all three incumbents run; TA 5 and TA 7 each have only the
--     incumbent). Pacheco + Green rows reused (2024 NetFile filers for these seats).
--   COMPTON CCD: 5 trustee areas; 2026 ballot TA 1, 4, 5 plus a SPECIAL election for TA 2 (unexpired term to Dec 2028).
--     TA 2: Barbara Jean Calhoun resigned effective Feb 1 2026; the board provisionally appointed Dr. Nicole J. Jones on
--     Mar 9 2026 (Resolution 03-09-2026A); she runs in the special. The college page lists her as "Provisional Appointment".
--   LONG BEACH CCD: 5 trustee areas; 2026 ballot TA 1, 3, 5. TA 5 is OPEN (Virginia Baxter is not on the list). TA 4
--     includes Santa Catalina Island (the precinct layer puts Avalon in DIV_JRC 4; the college page: "East Long Beach and
--     Catalina Island"). Vivian Malauulu's existing row is reused: its data_source named ABC Unified, a seat the CA_0156
--     audit disproved (her ABC term was removed then); the row is repointed to the LBCC board page.
--   EL CAMINO CCD: 5 trustee areas; 2026 ballot TA 2, 5. TA 5: Cliff Numark vacated Nov 10 2025; MyLoc Dinh was
--     provisionally appointed Dec 18 2025 (sworn in Jan 21 2026) and runs. Brett Roberts' row is reused (2024 NetFile filer).
--   Student trustees are not modeled (advisory vote only).
BEGIN;

-- ─── 1. Government + governing board (chamber) per college district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'Cerritos Community College District, California, US'),
    ('fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, 'Compton Community College District, California, US'),
    ('0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, 'Long Beach Community College District, California, US'),
    ('9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid, 'El Camino Community College District, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, election_frequency, website_url, policy_engagement_level)
SELECT v.id, v.gid, 'Board of Trustees', v.name_formal, '4 years', '4 years', v.url, 'full'   -- slug is generated
  FROM (VALUES
    ('e91f4b30-c490-5251-994e-19da700c97d3'::uuid, 'b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'Cerritos Community College District Board of Trustees', 'https://www.cerritos.edu/board/'),
    ('df792069-15ce-5839-a366-6ba2768c9919'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, 'Compton Community College District Board of Trustees', 'https://www.compton.edu/district/board-of-trustees/index.aspx'),
    ('5f44431e-cb19-51fd-a438-36a22d7fea11'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, 'Long Beach Community College District Board of Trustees', 'https://www.lbcc.edu/board-trustees'),
    ('a56b5352-8503-5ed7-9120-384254546cae'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid, 'El Camino Community College District Board of Trustees', 'https://www.elcamino.edu/leadership/trustees/index.php')
  ) AS v(id, gid, name_formal, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);

