-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X0002' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry);
  IF n <> 22 THEN RAISE EXCEPTION 'expected 22 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid) AND d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002';
  IF n <> 22 THEN RAISE EXCEPTION 'expected 22 SCHOOL districts, got %', n; END IF;

  -- every seat is held by exactly the trustee named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('840768e5-d0c2-55e8-86f0-5422eda08d74'::uuid, 'c319044d-eef8-4e75-9ef1-d6adfb2a6f3c'::uuid), ('fdadbc1c-a55c-572d-a5f0-3b0b9a00fe0b'::uuid, 'a8d55cc2-20fd-42c5-82ad-221574a51784'::uuid), ('dab84bcd-e43c-558d-b8cf-647ce1a6d57c'::uuid, '89a47fbf-d9ab-5620-be88-2cc09920ac4e'::uuid), ('d7ab6c13-4265-53a8-b486-658415e599d6'::uuid, 'c60accf8-bcd8-5fbd-942f-a38f42f593e8'::uuid), ('64ed20c6-1647-5c0b-89e7-96a61cbc2119'::uuid, '5c2847a8-aace-5c87-8059-f6046573e2aa'::uuid), ('903633c7-1476-5138-9d50-48df98433d0f'::uuid, '0c91d5a8-53bf-53a7-a18a-9892f73c3b19'::uuid), ('2df051b6-9896-5b40-bd30-b37e66c5e74e'::uuid, '48d4f532-32e4-5942-9479-e5d596715a3d'::uuid), ('505f1321-b3c5-5d37-8df4-3e1e0cb20cb2'::uuid, '81c74a05-bdac-52d6-b654-5cffe13f9495'::uuid), ('72790861-7f7d-59bf-8257-6c44e5f69a6f'::uuid, 'b0af4a0b-9b57-550d-95d4-6e40eeaf45e8'::uuid), ('7a7ae303-f6d2-508a-8494-dfb30ca072f6'::uuid, '4a59efd4-1e3e-507e-842c-653684b281e3'::uuid), ('31351aa3-5e7b-5228-808c-cbe3878c8f42'::uuid, '5df0ea63-3cbb-5c15-8b47-6496ac751eab'::uuid), ('d56b2789-5735-5f84-86ad-84dcb5dee519'::uuid, '0448a725-9517-5483-a6ce-78771442db1f'::uuid), ('500de311-8d8a-5cb6-b832-1536cc0cc397'::uuid, '0272f4a5-c7c4-5d92-88ab-8605e0bf7278'::uuid), ('8bec4ff4-9de9-540d-8378-038242b5d8fd'::uuid, '661de009-8046-4beb-ba70-420a862e78e8'::uuid), ('d7208e52-1040-5910-9581-fda775102e72'::uuid, '52c4fafe-3d3b-5e04-9c49-5ed9c2d33433'::uuid), ('cd19082f-29d7-5727-ada8-eecad09407a7'::uuid, '69d53405-665c-5df6-b245-2326089d5545'::uuid), ('ff7077e0-bd33-51f4-a7d8-e61ee39dec52'::uuid, '796ebfb5-6de7-528f-b302-10f5bb1c3837'::uuid), ('99ef58ea-5db2-5fa4-84ea-8933b41ba0ea'::uuid, '6b20c5ef-5566-4e8c-8180-1612af46852a'::uuid), ('070f2183-8233-577a-8891-f1ea5022b07f'::uuid, '6e164a30-75f2-59bb-87cd-8cd8ccd9d4cb'::uuid), ('12fcb4d6-d3b7-5855-aa84-4a2000ce5999'::uuid, '494aed48-8f09-5118-923a-f72274a583fe'::uuid), ('238b3058-9118-5cbf-ad11-8e7e1a65efd7'::uuid, '95795a21-dbca-53d0-8e64-f0be2c2b2e8f'::uuid), ('e1a37f90-3f31-5e87-b196-20db4713387d'::uuid, '22c801fe-5e44-5e81-b943-35f4774d41af'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 22 THEN RAISE EXCEPTION 'expected 22 seats each held by its named trustee, got %', n; END IF;
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid);
  IF n <> 22 THEN RAISE EXCEPTION 'expected 22 offices, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('840768e5-d0c2-55e8-86f0-5422eda08d74'::uuid, 'c319044d-eef8-4e75-9ef1-d6adfb2a6f3c'::uuid), ('fdadbc1c-a55c-572d-a5f0-3b0b9a00fe0b'::uuid, 'a8d55cc2-20fd-42c5-82ad-221574a51784'::uuid), ('dab84bcd-e43c-558d-b8cf-647ce1a6d57c'::uuid, '89a47fbf-d9ab-5620-be88-2cc09920ac4e'::uuid), ('d7ab6c13-4265-53a8-b486-658415e599d6'::uuid, 'c60accf8-bcd8-5fbd-942f-a38f42f593e8'::uuid), ('64ed20c6-1647-5c0b-89e7-96a61cbc2119'::uuid, '5c2847a8-aace-5c87-8059-f6046573e2aa'::uuid), ('903633c7-1476-5138-9d50-48df98433d0f'::uuid, '0c91d5a8-53bf-53a7-a18a-9892f73c3b19'::uuid), ('2df051b6-9896-5b40-bd30-b37e66c5e74e'::uuid, '48d4f532-32e4-5942-9479-e5d596715a3d'::uuid), ('505f1321-b3c5-5d37-8df4-3e1e0cb20cb2'::uuid, '81c74a05-bdac-52d6-b654-5cffe13f9495'::uuid), ('72790861-7f7d-59bf-8257-6c44e5f69a6f'::uuid, 'b0af4a0b-9b57-550d-95d4-6e40eeaf45e8'::uuid), ('7a7ae303-f6d2-508a-8494-dfb30ca072f6'::uuid, '4a59efd4-1e3e-507e-842c-653684b281e3'::uuid), ('31351aa3-5e7b-5228-808c-cbe3878c8f42'::uuid, '5df0ea63-3cbb-5c15-8b47-6496ac751eab'::uuid), ('d56b2789-5735-5f84-86ad-84dcb5dee519'::uuid, '0448a725-9517-5483-a6ce-78771442db1f'::uuid), ('500de311-8d8a-5cb6-b832-1536cc0cc397'::uuid, '0272f4a5-c7c4-5d92-88ab-8605e0bf7278'::uuid), ('8bec4ff4-9de9-540d-8378-038242b5d8fd'::uuid, '661de009-8046-4beb-ba70-420a862e78e8'::uuid), ('d7208e52-1040-5910-9581-fda775102e72'::uuid, '52c4fafe-3d3b-5e04-9c49-5ed9c2d33433'::uuid), ('cd19082f-29d7-5727-ada8-eecad09407a7'::uuid, '69d53405-665c-5df6-b245-2326089d5545'::uuid), ('ff7077e0-bd33-51f4-a7d8-e61ee39dec52'::uuid, '796ebfb5-6de7-528f-b302-10f5bb1c3837'::uuid), ('99ef58ea-5db2-5fa4-84ea-8933b41ba0ea'::uuid, '6b20c5ef-5566-4e8c-8180-1612af46852a'::uuid), ('070f2183-8233-577a-8891-f1ea5022b07f'::uuid, '6e164a30-75f2-59bb-87cd-8cd8ccd9d4cb'::uuid), ('12fcb4d6-d3b7-5855-aa84-4a2000ce5999'::uuid, '494aed48-8f09-5118-923a-f72274a583fe'::uuid), ('238b3058-9118-5cbf-ad11-8e7e1a65efd7'::uuid, '95795a21-dbca-53d0-8e64-f0be2c2b2e8f'::uuid), ('e1a37f90-3f31-5e87-b196-20db4713387d'::uuid, '22c801fe-5e44-5e81-b943-35f4774d41af'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated trustee row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two trustee areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X0002'
   WHERE a.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee-area pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> X0002 SCHOOL district -> office -> holder)
  -- to exactly that district's own trustee(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE me.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X0002'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own trustee(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid);
  IF n <> 12 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 12 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid);
  IF n <> 19 THEN RAISE EXCEPTION 'expected 19 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a trustee seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('b25debb6-27ee-5350-913e-d55f5aec7c20'::uuid, 'fb8a6c6f-6094-5612-b70d-79c0e703d195'::uuid, '0ab5e92a-3590-5997-aadb-a522959f043c'::uuid, '9fccdb72-fd61-504d-afe2-ddb95d0d1e46'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated trustee', n; END IF;

  RAISE NOTICE 'CA_0219 applied: 4 boards, 22 polygons, 22 seats, 12 races, 19 candidates';
END $$;

COMMIT;
